    """
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i in range(10):
            if isbn[i] == 'X':
                total += 10 * (11 - i)
            else:
                total += int(isbn[i]) * (11 - i)
        return total % 11

    # Remove hyphens from the ISBN number
