    # Calculate the current checksum
    current_checksum = calculate_checksum(isbn[:-1])

    # Check if the current checksum matches the last digit
    if current_checksum == 0:
        if isbn[-1] == '0':
            return "Right"
        else:
            corrected_isbn = isbn[:-1] + '0'
            return corrected_isbn
    else:
        expected_checksum = 11 - current_checksum
        if expected_checksum == 10:
            expected_checksum = 'X'
        if isbn[-1] == 'X':
            corrected_isbn = isbn[:-1] + expected_checksum
            return corrected_isbn
        else:
            return "Right"

